/* Contenido profundo de es_p5 (borrador para revisión del equipo curricular; ver "verify" por unidad). */
window.EL_DEEP = window.EL_DEEP || {};
Object.assign(window.EL_DEEP, {"p5:Oct": {"reading": ["Cuando un niño de tu edad mira un mapa de la Europa del siglo XVI, le sorprende descubrir que buena parte de él pertenecía a una misma familia reinante. Esa familia era la de los Habsburgo, y su figura central en España fue Carlos I, nieto de los Reyes Católicos por parte de madre y del emperador Maximiliano por parte de padre. Heredó, siendo todavía muy joven, las coronas de Castilla y de Aragón en el año 1516, y poco después, en 1519, fue elegido emperador del Sacro Imperio Romano Germánico, título con el que se le conoce en Europa como Carlos V. Por eso solemos decir que fue el primer rey de las coronas españolas unidas bajo un solo monarca, aunque cada reino conservó durante mucho tiempo sus leyes e instituciones propias.", "Gobernar tantos territorios resultaba una tarea inmensa. Carlos I tuvo que viajar sin descanso entre España, los Países Bajos, Alemania e Italia, porque no existía una capital fija ni los medios de comunicación que hoy conocemos. Además, tuvo que defender sus dominios frente a Francia, frente al avance del Imperio otomano en el Mediterráneo y frente a la división religiosa que la Reforma protestante provocó en Alemania. Su idea de gobierno se apoyaba en la unidad de la cristiandad, es decir, en la convicción de que los pueblos europeos debían permanecer unidos en una misma fe. Hacia el final de su vida, cansado y enfermo, abdicó en 1556 y se retiró a un monasterio de Extremadura, dejando a su hijo Felipe la mayor parte de sus reinos.", "Felipe II reinó desde 1556 hasta 1598 y tuvo un carácter muy distinto al de su padre. Mientras Carlos I fue un rey viajero y guerrero, Felipe fue un rey sedentario, trabajador y minucioso, que despachaba personalmente una enorme cantidad de papeles desde su mesa. Estableció la corte de manera estable en Madrid y gobernó mediante consejos y secretarios, de modo que se le llamó «el rey prudente». Durante su reinado, en el año 1580, la corona de Portugal quedó unida a la suya, y con ella pasaron a su autoridad las posesiones portuguesas de África, Asia y Brasil. Fue entonces cuando se dijo que en sus dominios «nunca se ponía el sol», porque siempre era de día en alguno de sus territorios, repartidos entre Europa, América, África y Asia.", "El gran símbolo del reinado de Felipe II es el monasterio de San Lorenzo de El Escorial, cerca de Madrid. Sus obras comenzaron en 1563 y terminaron en 1584. Era a la vez palacio, monasterio, basílica, biblioteca y panteón de reyes. Esta mezcla nos enseña mucho sobre la mentalidad de la época: el rey quería que el poder político estuviera acompañado de oración y de estudio. Por eso el edificio, de líneas sobrias y severas, albergaba una comunidad de monjes que rezaba por la familia real y una biblioteca con miles de volúmenes. El Escorial expresa la unión entre la fe y el poder tal como la entendían los reyes de entonces, una unión que trajo grandes bienes, pero que también les exigía una responsabilidad muy grande ante Dios.", "Esa responsabilidad aparece en el versículo que estudiamos este mes: «El rey que juzga con verdad a los pobres, afirmará su trono para siempre». El libro de Proverbios enseña que un gobernante no se mide por la extensión de sus territorios, sino por la justicia con que trata a los más débiles. Aplicado a nuestro tema, nos invita a hacernos preguntas honestas. Los reyes de este periodo lograron reunir pueblos lejanos, difundir la lengua y levantar universidades y hospitales. Pero también cometieron errores, sostuvieron guerras agotadoras y dejaron deudas que debilitaron a la Hacienda. Un buen estudiante de Historia aprende a reconocer los aciertos sin esconder los fallos, y sabe que juzgar a las personas del pasado requiere paciencia, datos y humildad.", "Para estudiar este imperio conviene recordar tres ideas. La primera es que se formó por una combinación de herencias familiares, matrimonios y conquistas, y no por un plan único trazado desde el principio. La segunda es que sus territorios eran muy diversos: los Países Bajos, el sur de Italia, Milán, las Indias occidentales y, más tarde, Filipinas tenían costumbres, leyes y lenguas diferentes. La tercera es que la defensa de la fe católica era, para estos monarcas, un motivo central de su política, como se ve en la batalla naval de Lepanto, en 1571, donde una flota cristiana frenó el poder otomano en el Mediterráneo. Con estas ideas podrás comparar a ambos reyes y comprender por qué su legado, grande y complejo, sigue siendo tema de estudio en el mundo entero."], "glossary": [{"term": "Habsburgo", "def": "Familia europea de origen austriaco que reinó en España desde Carlos I hasta finales del siglo XVII."}, {"term": "Abdicar", "def": "Renunciar un rey voluntariamente a su corona y traspasarla a otra persona."}, {"term": "Sacro Imperio Romano Germánico", "def": "Conjunto de territorios de Europa central gobernados por un emperador elegido por príncipes alemanes."}, {"term": "Corte", "def": "Conjunto de personas, consejeros y servidores que rodean al rey y le ayudan a gobernar."}, {"term": "Monasterio", "def": "Edificio donde vive una comunidad de monjes dedicada a la oración, el estudio y el trabajo."}, {"term": "Panteón", "def": "Lugar donde se entierra a los miembros de una familia ilustre, en este caso la familia real."}, {"term": "Reforma protestante", "def": "Movimiento religioso iniciado en Alemania en el siglo XVI que dividió a los cristianos de Europa occidental."}], "practice": [{"q": "Explica con tus propias palabras por qué se dice que Carlos I fue el primer rey de las coronas españolas unidas y qué dificultades tuvo para gobernar tantos territorios.", "feedback": "Carlos I heredó Castilla y Aragón, y por primera vez ambas coronas quedaron bajo un mismo rey, aunque cada reino mantuvo sus leyes. Gobernar tantos territorios era difícil porque estaban muy lejos entre sí y no había capital fija ni comunicaciones rápidas. Además, debía defenderse de Francia, de los otomanos y de la división religiosa de Alemania. Por eso viajó continuamente por Europa. Una buena respuesta menciona la herencia, la distancia y los conflictos."}, {"q": "Compara el estilo de gobierno de Carlos I con el de Felipe II. Escribe dos diferencias y una semejanza.", "feedback": "Carlos I fue un rey viajero y guerrero, mientras que Felipe II fue sedentario y trabajaba desde los despachos de su corte en Madrid. Una segunda diferencia es que Carlos I también fue emperador del Sacro Imperio, mientras que Felipe II centró su poder en la monarquía hispánica. Como semejanza, ambos consideraron la defensa de la fe católica un motivo central de su política y gobernaron con ayuda de consejeros. Lo importante es apoyar cada comparación en datos del texto."}, {"q": "¿Qué nos enseña el monasterio de El Escorial sobre la mentalidad de Felipe II? Relaciónalo con Proverbios 29:14.", "feedback": "El Escorial reunía palacio, monasterio, biblioteca y panteón, lo que muestra que el rey quería unir el poder con la oración y el estudio. Proverbios 29:14 recuerda que el trono se afirma cuando el rey juzga con verdad a los pobres, es decir, con justicia. El edificio expresa el deseo de gobernar bajo la mirada de Dios, aunque el verdadero criterio es si se practicó la justicia. Así se conecta la arquitectura con la responsabilidad moral del gobernante."}, {"q": "¿Por qué decimos que un buen historiador debe reconocer aciertos y errores de los reyes del pasado? Pon un ejemplo del texto.", "feedback": "Porque la verdad histórica exige mirar los hechos completos, sin exaltar ni condenar sin pruebas. Los reyes de este periodo unieron pueblos, difundieron la lengua y fundaron instituciones, pero también sostuvieron guerras costosas y dejaron deudas. Si solo contáramos los éxitos, ofreceríamos una imagen falsa, y lo mismo ocurriría si solo contáramos los fallos. Esta actitud de honestidad concuerda con la enseñanza bíblica de buscar siempre la verdad."}], "quiz": [{"q": "¿Qué dos coronas heredó Carlos I en 1516, según la lectura?", "opts": [{"t": "Las de Castilla y Aragón", "ok": true}, {"t": "Las de Francia e Inglaterra", "ok": false}, {"t": "Las de Portugal y Navarra", "ok": false}]}, {"q": "¿Qué diferencia principal señala la lectura entre Carlos I y Felipe II?", "opts": [{"t": "Felipe II viajaba constantemente y Carlos I nunca salía de España", "ok": false}, {"t": "Carlos I era un rey viajero y Felipe II gobernaba de forma sedentaria desde su corte", "ok": true}, {"t": "Carlos I era protestante y Felipe II católico", "ok": false}]}, {"q": "¿Por qué se decía que en los dominios de Felipe II nunca se ponía el sol?", "opts": [{"t": "Porque el clima de España era siempre soleado", "ok": false}, {"t": "Porque sus territorios estaban repartidos por varios continentes", "ok": true}, {"t": "Porque el rey ordenó que las luces no se apagaran", "ok": false}]}, {"q": "¿Qué función tuvo el monasterio de El Escorial?", "opts": [{"t": "Era solo una fortaleza militar", "ok": false}, {"t": "Era solamente una escuela de artesanos", "ok": false}, {"t": "Era palacio, monasterio, biblioteca y panteón real a la vez", "ok": true}]}, {"q": "¿Qué enseña Proverbios 29:14 aplicado a los gobernantes?", "opts": [{"t": "Que el trono se afirma cuando el rey juzga con verdad a los pobres", "ok": true}, {"t": "Que el rey debe conquistar cuantas más tierras mejor", "ok": false}, {"t": "Que los reyes no deben rendir cuentas a nadie", "ok": false}]}], "verify": ["Carlos I: herencia de Castilla y Aragón en 1516 y elección imperial en 1519", "Abdicación de Carlos I en 1556 y retiro a un monasterio de Extremadura (Yuste)", "Reinado de Felipe II 1556-1598 y unión con Portugal en 1580", "Obras de El Escorial 1563-1584", "Batalla de Lepanto, 1571", "Atribución de la frase «nunca se pone el sol» (uso popular, no cita oficial)"], "timeline": [{"when": "1516", "what": "Carlos I hereda las coronas de Castilla y de Aragón."}, {"when": "1519", "what": "Carlos es elegido emperador del Sacro Imperio: Carlos V."}, {"when": "1556", "what": "Carlos abdica y su hijo Felipe II comienza a reinar."}, {"when": "1563", "what": "Comienzan las obras del monasterio de El Escorial."}, {"when": "1571", "what": "La flota cristiana frena a los otomanos en Lepanto."}, {"when": "1580", "what": "Portugal queda unido a la corona de Felipe II."}, {"when": "1584", "what": "Terminan las obras de El Escorial."}], "scene": {"icons": ["👑", "🏰", "⚓"], "palette": "amber"}, "media": [{"title": "Carlos V en la batalla de Mühlberg (Tiziano)", "what": "Retrato ecuestre del emperador que muestra su poder y su papel de defensor de la fe.", "find": "Carlos V en Mühlberg Tiziano Museo del Prado", "note": "Tiziano, 1548; pintura antigua de dominio público"}, {"title": "Monasterio de San Lorenzo de El Escorial", "what": "Vista del gran símbolo del reinado de Felipe II: palacio, monasterio y biblioteca.", "find": "Monasterio de El Escorial fachada", "note": "Obra del siglo XVI; fotografía moderna, verificar licencia"}, {"title": "Retrato de Felipe II (Sofonisba Anguissola)", "what": "Muestra al rey prudente, sobrio y trabajador.", "find": "Felipe II Sofonisba Anguissola Prado", "note": "Sofonisba Anguissola, hacia 1573; dominio público"}], "map": {"region": "iberia", "markers": [{"name": "Madrid", "lat": 40.4, "lon": -3.7, "kind": "city"}, {"name": "Monasterio de El Escorial", "lat": 40.6, "lon": -4.1, "kind": "site"}, {"name": "Monasterio de Yuste (Extremadura)", "lat": 40.1, "lon": -5.8, "kind": "site"}]}}, "p5:Nov": {"reading": ["Conocer el lugar donde vivimos es una forma de agradecer a Dios el mundo que nos ha dado. España se encuentra en el suroeste de Europa, en un territorio llamado península ibérica, que comparte con Portugal y con el pequeño país de Andorra en la zona pirenaica. Está rodeada de agua casi por completo: el mar Mediterráneo baña su costa oriental y meridional, el océano Atlántico la costa occidental y el mar Cantábrico la costa norte. Solo por el noreste y por el oeste limita por tierra con otros países. Esta situación geográfica, entre dos mares y a pocos kilómetros de África, explica por qué España ha sido durante siglos un lugar de encuentro de pueblos, rutas comerciales y culturas.", "Las fronteras terrestres de España son pocas y fáciles de recordar. Al norte, la cordillera de los Pirineos separa a España de Francia y de Andorra. Esta cadena de montañas funciona como una muralla natural que durante la Edad Media dificultó mucho el paso de ejércitos y de viajeros. Al oeste, España limita con Portugal, y buena parte de esa frontera la marcan ríos como el Miño, el Duero, el Tajo y el Guadiana, que nacen en tierras españolas y desembocan en el Atlántico, ya en territorio portugués. Además, en el norte de África las ciudades españolas de Ceuta y Melilla tienen frontera con Marruecos, y en el extremo sur de la península el territorio de Gibraltar está bajo administración del Reino Unido, un asunto que sigue siendo objeto de conversaciones diplomáticas.", "Los países vecinos tienen cada uno su capital, y conviene aprenderlas con ayuda del mapa. La capital de Francia es París, la de Portugal es Lisboa, la de Andorra es Andorra la Vella y la de España es Madrid, situada casi en el centro de la península. Si ampliamos la mirada al resto de Europa, aparecen otras naciones importantes como Italia, con Roma, y Alemania, con Berlín. Compararlas en extensión nos ayuda a pensar con orden: Francia metropolitana es algo mayor que España, mientras que España es más extensa que Alemania y que Italia. Sin embargo, el tamaño no determina la importancia de un país. Lo que cuenta es lo que sus habitantes hacen con lo que tienen, su historia y sus aportaciones a la humanidad.", "España forma parte de la Unión Europea, una asociación de países europeos que deciden cooperar en economía, leyes y seguridad para vivir en paz y prosperidad. Después de las terribles guerras del siglo XX, varios países comprendieron que era mejor colaborar que enfrentarse. España ingresó en lo que entonces se llamaba Comunidad Europea en 1986. Entre los beneficios que obtuvo están la libre circulación de personas y mercancías, ayudas para construir carreteras, trenes y escuelas, y un mercado muy amplio para vender sus productos, como el aceite de oliva, el vino o las frutas. A su vez, España aporta su agricultura, su turismo, su lengua, su cultura y el trabajo de millones de personas. Con el tiempo, muchos países de la Unión adoptaron una moneda común, el euro, que circula en España desde principios del siglo XXI.", "Como cristianos, miramos la geografía con una mirada especial. El apóstol Pablo, hablando en Atenas, afirmó que Dios «de una sangre ha hecho todo el linaje humano para que habite sobre toda la faz de la tierra», y que «les ha prefijado el orden de los tiempos y los límites de su habitación». Esto significa que las naciones no son un accidente, sino que están dentro del plan de Dios, que gobierna la historia. También significa que todos los pueblos, vivan a un lado u otro de una frontera, proceden de un mismo origen y merecen respeto. Las fronteras son límites políticos que sirven para ordenar la vida de las naciones, pero no deben convertirse en motivo de desprecio hacia quien vive al otro lado.", "Para trabajar bien con los mapas de Europa recuerda algunas técnicas. Primero, localiza los mares y las cordilleras, que te sirven de referencia. Segundo, colorea cada país con un color distinto y escribe su capital con letra clara. Tercero, usa la escala del mapa para comparar distancias entre ciudades. Y cuarto, anota siempre la fuente de la que has sacado los datos, porque un buen geógrafo no copia sin comprobar. Con estas herramientas podrás elaborar una ficha de la Unión Europea ordenada y un mapa de España en Europa que muestre con precisión sus fronteras y a sus vecinos. Así aprenderás a ver tu país dentro de un continente mayor, como una pieza que colabora con las demás."], "glossary": [{"term": "Península", "def": "Porción de tierra rodeada de agua por todas partes excepto por una, por la que se une al continente."}, {"term": "Frontera", "def": "Línea que separa el territorio de un país del de otro."}, {"term": "Cordillera", "def": "Conjunto de montañas encadenadas, como los Pirineos."}, {"term": "Capital", "def": "Ciudad donde reside el gobierno principal de un país."}, {"term": "Unión Europea", "def": "Asociación de países europeos que cooperan en economía, leyes y seguridad."}, {"term": "Extensión", "def": "Superficie que ocupa un territorio, que se mide en kilómetros cuadrados."}, {"term": "Escala", "def": "Relación entre una distancia dibujada en el mapa y la distancia real sobre el terreno."}], "practice": [{"q": "Describe la situación de España en Europa: qué mares la rodean y con qué países limita por tierra.", "feedback": "España se sitúa en el suroeste de Europa, en la península ibérica. La rodean el Mediterráneo, el Atlántico y el Cantábrico. Limita por tierra con Francia y Andorra, a través de los Pirineos, y con Portugal al oeste. Además, Ceuta y Melilla limitan con Marruecos, y Gibraltar está bajo administración británica. Una respuesta completa nombra los mares y los vecinos con precisión."}, {"q": "Explica por qué los Pirineos y los ríos son importantes para entender las fronteras de España.", "feedback": "Los Pirineos forman una barrera natural entre España y Francia que durante siglos dificultó el paso de ejércitos y viajeros. Los ríos como el Miño o el Tajo señalan o cruzan la zona fronteriza con Portugal. En ambos casos, los accidentes geográficos ayudan a trazar límites, porque son fáciles de reconocer en el terreno. Aun así, hay fronteras fijadas por tratados y no solo por la naturaleza."}, {"q": "Menciona dos beneficios que España recibe de la Unión Europea y dos aportaciones que hace.", "feedback": "Entre los beneficios están la libre circulación de personas y mercancías y las ayudas para obras públicas, como carreteras o escuelas. Entre las aportaciones figuran la producción agrícola, el turismo y la riqueza cultural y lingüística. Lo importante es entender que la cooperación es mutua: cada país recibe y también ofrece algo valioso a los demás."}, {"q": "¿Qué enseña Hechos 17:26 sobre las naciones y las fronteras? ¿Qué actitud debemos tener hacia otros pueblos?", "feedback": "Hechos 17:26 enseña que todos los seres humanos proceden de un mismo origen y que Dios ha fijado los tiempos y los límites de las naciones. Por tanto, las fronteras no son motivo para despreciar a nadie, ya que todos compartimos la misma dignidad como criaturas de Dios. La actitud correcta es el respeto, la cooperación y el deseo del bien para otros pueblos."}], "quiz": [{"q": "¿Qué cordillera separa España de Francia y de Andorra?", "opts": [{"t": "Los Pirineos", "ok": true}, {"t": "Los Alpes", "ok": false}, {"t": "Sierra Nevada", "ok": false}]}, {"q": "¿Cuál es la capital de Portugal?", "opts": [{"t": "Oporto", "ok": false}, {"t": "Madrid", "ok": false}, {"t": "Lisboa", "ok": true}]}, {"q": "Según la lectura, ¿qué ocurre con el tamaño de los países al compararlos?", "opts": [{"t": "España es mayor que Francia metropolitana", "ok": false}, {"t": "Francia metropolitana es algo mayor que España, y España es mayor que Alemania e Italia", "ok": true}, {"t": "Todos los países europeos tienen la misma extensión", "ok": false}]}, {"q": "¿Por qué varios países europeos decidieron cooperar en la Unión Europea?", "opts": [{"t": "Porque comprendieron tras las guerras del siglo XX que era mejor colaborar que enfrentarse", "ok": true}, {"t": "Porque querían eliminar sus lenguas propias", "ok": false}, {"t": "Porque no tenían fronteras", "ok": false}]}, {"q": "¿Qué enseña Hechos 17:26 sobre las naciones?", "opts": [{"t": "Que unas naciones valen más que otras", "ok": false}, {"t": "Que las naciones no tienen relación con Dios", "ok": false}, {"t": "Que todos los pueblos proceden de un mismo origen y están dentro del plan de Dios", "ok": true}]}], "verify": ["Ingreso de España en la Comunidad Europea en 1986", "Comparación de extensión: Francia metropolitana algo mayor que España; España mayor que Alemania e Italia", "Ríos que marcan o cruzan la frontera con Portugal (Miño, Duero, Tajo, Guadiana)", "Estatus de Gibraltar (administración británica) y de Ceuta y Melilla", "Capitales de los países vecinos: París, Lisboa, Andorra la Vella", "Cita de Hechos 17:26 en versión Reina-Valera (comprobar redacción)"], "timeline": [{"when": "Paso 1", "what": "Localiza los mares y las cordilleras como referencia."}, {"when": "Paso 2", "what": "Colorea cada país con un color distinto."}, {"when": "Paso 3", "what": "Escribe la capital de cada país con letra clara."}, {"when": "Paso 4", "what": "Usa la escala del mapa para comparar distancias."}, {"when": "Paso 5", "what": "Anota la fuente de la que sacas los datos."}, {"when": "Paso 6", "what": "Elabora la ficha de la Unión Europea y el mapa final."}], "scene": {"icons": ["🗺️", "🇪🇺", "🏔️"], "palette": "blue"}, "media": [{"title": "Mapa político de Europa", "what": "Permite localizar países vecinos, capitales y mares.", "find": "political map of Europe blank", "note": "Hay versiones libres en Commons; verificar licencia"}, {"title": "Mapa físico de la península ibérica", "what": "Muestra Pirineos, ríos y costas que rodean a España.", "find": "Iberian Peninsula relief map", "note": "Mapa moderno; verificar licencia"}, {"title": "Bandera de la Unión Europea", "what": "Símbolo de la asociación de países que estudia la unidad.", "find": "Flag of Europe", "note": "Imagen de uso libre en Commons; verificar licencia"}], "map": {"region": "iberia", "markers": [{"name": "Madrid", "lat": 40.4, "lon": -3.7, "kind": "city"}, {"name": "Lisboa", "lat": 38.7, "lon": -9.1, "kind": "city"}, {"name": "Andorra la Vella", "lat": 42.5, "lon": 1.5, "kind": "city"}, {"name": "Pirineos", "lat": 42.7, "lon": 0.5, "kind": "mountain"}, {"name": "Río Miño (desembocadura)", "lat": 41.9, "lon": -8.9, "kind": "river"}, {"name": "Río Duero (desembocadura)", "lat": 41.1, "lon": -8.7, "kind": "river"}, {"name": "Río Tajo (desembocadura)", "lat": 38.7, "lon": -9.2, "kind": "river"}, {"name": "Río Guadiana (desembocadura)", "lat": 37.2, "lon": -7.4, "kind": "river"}, {"name": "Ceuta", "lat": 35.9, "lon": -5.3, "kind": "city"}, {"name": "Gibraltar", "lat": 36.1, "lon": -5.4, "kind": "city"}]}}, "p5:Dic": {"reading": ["Cada día escuchamos personas que defienden lo que piensan: un amigo que quiere elegir el juego, un vecino que reclama una mejora, un autor que escribe en un periódico. Cuando alguien defiende una idea con razones, está argumentando. El texto argumentativo es aquel cuyo propósito principal es convencer al lector de que una opinión es acertada, apoyándola con pruebas. No se trata de ganar una pelea, sino de ofrecer buenos motivos para que otra persona piense con libertad y llegue a una conclusión. Por eso decimos que argumentar bien es una forma de respetar a quien nos lee o nos escucha.", "Todo texto argumentativo claro tiene tres partes. La primera es la tesis, que es la idea central que el autor quiere defender. Debe formularse de manera precisa, por ejemplo: «La Reconquista fue un proceso largo que marcó profundamente la identidad de España». La segunda parte es el cuerpo argumentativo, donde se presentan los argumentos, es decir, las razones que sostienen la tesis. Un argumento será más sólido cuanto más se apoye en hechos comprobables. La tercera parte es la conclusión, que recoge la tesis a la luz de lo expuesto y deja una idea final. Si falta alguna de estas partes, el texto resulta confuso: sin tesis no se sabe qué se defiende, y sin pruebas la opinión queda en simple capricho.", "En esta unidad aprenderás a argumentar con datos históricos. Un dato histórico puede ser una fecha, un acontecimiento, un documento o el testimonio de una persona de la época. Si queremos opinar sobre la Reconquista, el proceso por el que los reinos cristianos de la península fueron recuperando territorios dominados desde el año 711 hasta la toma de Granada en 1492, tenemos que conocer los hechos antes de juzgarlos. Un argumento a favor podría señalar que, durante esos siglos, se formaron reinos, leyes y una lengua común que dieron forma a España. Un argumento en contra o matizado recordaría que hubo violencia, que existieron periodos de convivencia entre religiones y que la historia no se resume en un único color. Un texto honesto reconoce la complejidad.", "Para que los argumentos se entiendan y se enlacen, usamos los conectores argumentativos. Son palabras o expresiones que unen las ideas y muestran la relación entre ellas. Para añadir razones empleamos «además», «asimismo» o «también». Para indicar causa usamos «porque», «puesto que» o «ya que». Para señalar consecuencia, «por tanto», «de modo que» o «en consecuencia». Para contrastar, «sin embargo», «no obstante» o «en cambio». Y para concluir, «en definitiva», «en resumen» o «por último». Un ejemplo sencillo sería: «La Reconquista duró siglos; por tanto, no puede explicarse con una sola fecha». Observa que después de algunos conectores se escribe coma, y que su elección cambia el sentido de la frase.", "También debemos cuidar la puntuación, porque una coma o un punto mal colocados alteran el significado. Se usa la coma para separar los elementos de una enumeración, para aislar los conectores como «sin embargo» y para marcar una aclaración intercalada. El punto y coma separa ideas relacionadas pero más largas que una simple enumeración. El punto cierra una oración completa. Al corregir un texto, lee en voz alta y observa dónde haces una pausa natural. Una buena corrección busca tres cosas: que cada oración tenga sentido completo, que las mayúsculas y las tildes estén bien colocadas y que las ideas sigan un orden lógico.", "Detrás de toda esta técnica hay un valor cristiano. El apóstol Pablo escribe en Efesios 4:15 que debemos hablar «la verdad en amor». Eso significa que, al debatir, no estamos autorizados a deformar los hechos ni a ridiculizar a quien piensa distinto. Tampoco debemos callar la verdad por miedo. El debate honesto exige tres actitudes: escuchar antes de responder, citar los datos con exactitud y tratar al otro con respeto. Quien argumenta de este modo se parece a un buen maestro, que explica con claridad y deja que el alumno piense. Cuando escribas tu texto sobre la Reconquista, procura que cada afirmación tenga una razón y que cada razón tenga un dato."], "glossary": [{"term": "Texto argumentativo", "def": "Texto cuyo propósito es convencer al lector mediante razones y pruebas."}, {"term": "Tesis", "def": "Idea central que el autor defiende en un texto argumentativo."}, {"term": "Argumento", "def": "Razón o prueba que se ofrece para apoyar una tesis."}, {"term": "Conclusión", "def": "Parte final del texto que recoge la tesis y cierra el razonamiento."}, {"term": "Conector", "def": "Palabra o expresión que enlaza ideas y muestra la relación lógica entre ellas."}, {"term": "Reconquista", "def": "Proceso histórico de recuperación de territorios peninsulares por los reinos cristianos, entre los siglos VIII y XV."}, {"term": "Puntuación", "def": "Conjunto de signos, como la coma o el punto, que organizan la lectura y el sentido de un escrito."}, {"term": "Dato histórico", "def": "Hecho comprobable, como una fecha o un documento, que sirve de prueba en un argumento."}], "practice": [{"q": "Explica las tres partes de un texto argumentativo y para qué sirve cada una.", "feedback": "La tesis presenta la idea que se quiere defender. Los argumentos ofrecen las razones y los datos que la apoyan. La conclusión retoma la tesis y cierra el texto con una idea final. Cada parte cumple una función necesaria: sin tesis no sabemos qué se defiende, sin argumentos la opinión carece de fuerza y sin conclusión el lector queda sin cierre."}, {"q": "Redacta una tesis sobre la Reconquista y escribe un argumento apoyado en un dato histórico. Usa un conector.", "feedback": "Un ejemplo válido: «La Reconquista fue un proceso largo que ayudó a formar la identidad de España. Además, durante esos siglos surgieron reinos y leyes propias, ya que cada territorio recuperado necesitaba organizarse». La respuesta debe tener una tesis clara, un dato verificable y un conector bien usado. Si el dato es dudoso, conviene expresarlo con generalidad, por ejemplo «durante la Edad Media»."}, {"q": "Une estas ideas con un conector adecuado: «La Reconquista duró siglos». «No puede explicarse con una sola fecha».", "feedback": "Podemos escribir: «La Reconquista duró siglos; por tanto, no puede explicarse con una sola fecha». También sería válido «de modo que» o «en consecuencia». El conector expresa consecuencia, porque la segunda idea se deduce de la primera. Es importante colocar la puntuación adecuada, como el punto y coma o la coma después de «por tanto»."}, {"q": "¿Cómo se relaciona Efesios 4:15 con la forma de debatir? Menciona dos actitudes concretas.", "feedback": "Hablar la verdad en amor significa defender las ideas con exactitud, sin mentir ni burlarse de nadie. Dos actitudes concretas son escuchar con atención antes de responder y citar los datos con fidelidad. De este modo el debate se convierte en un servicio al otro y no en un combate. La honestidad y el respeto son virtudes cristianas que mejoran cualquier argumento."}], "quiz": [{"q": "¿Qué es la tesis en un texto argumentativo?", "opts": [{"t": "La idea central que el autor defiende", "ok": true}, {"t": "La última frase del texto", "ok": false}, {"t": "Una lista de palabras difíciles", "ok": false}]}, {"q": "¿Cuál de estos conectores expresa consecuencia?", "opts": [{"t": "Sin embargo", "ok": false}, {"t": "Por tanto", "ok": true}, {"t": "Porque", "ok": false}]}, {"q": "¿Qué hace más sólido a un argumento según la lectura?", "opts": [{"t": "Que sea muy largo", "ok": false}, {"t": "Que se repita varias veces", "ok": false}, {"t": "Que se apoye en hechos comprobables", "ok": true}]}, {"q": "¿Qué actitud pide Efesios 4:15 a quien debate?", "opts": [{"t": "Hablar la verdad en amor", "ok": true}, {"t": "Imponer la propia opinión", "ok": false}, {"t": "Evitar siempre toda discusión", "ok": false}]}, {"q": "Según la lectura, ¿cómo debe tratar un texto honesto el tema de la Reconquista?", "opts": [{"t": "Presentándola como un hecho sin ninguna complejidad", "ok": false}, {"t": "Reconociendo que fue un proceso complejo, con luces y sombras", "ok": true}, {"t": "Evitando mencionar fechas", "ok": false}]}], "verify": ["Fechas simbólicas de la Reconquista: 711 y toma de Granada en 1492", "Cita de Efesios 4:15 en la versión empleada por el centro", "Coherencia de los ejemplos de conectores con la normativa de la RAE sobre puntuación"], "timeline": [{"when": "Paso 1", "what": "Formula la tesis: la idea central que defiendes."}, {"when": "Paso 2", "what": "Reúne datos históricos: fechas, hechos y documentos."}, {"when": "Paso 3", "what": "Escribe el cuerpo con argumentos que sostengan la tesis."}, {"when": "Paso 4", "what": "Enlaza las ideas con conectores argumentativos."}, {"when": "Paso 5", "what": "Escribe la conclusión que retoma la tesis."}, {"when": "Paso 6", "what": "Corrige la puntuación, las tildes y el orden lógico."}], "scene": {"icons": ["💬", "📝", "⚖️"], "palette": "violet"}, "media": [{"title": "La rendición de Granada (Pradilla)", "what": "Pintura sobre la toma de Granada en 1492, dato histórico para argumentar sobre la Reconquista.", "find": "Rendición de Granada Francisco Pradilla", "note": "Francisco Pradilla, 1882; dominio público"}, {"title": "Mapa de la Reconquista", "what": "Esquema del avance de los reinos cristianos desde 711 hasta 1492.", "find": "Reconquista map Iberian Peninsula", "note": "Hay varios mapas en Commons; verificar licencia"}, {"title": "La Alhambra de Granada", "what": "Recuerda el último reino musulmán de la península y la convivencia y los conflictos de la época.", "find": "Alhambra Granada Patio de los Leones", "note": "Fotografía; verificar licencia"}]}, "p5:Feb": {"reading": ["El 12 de octubre de 1492 es una de las fechas más importantes de la historia universal. Ese día, tras una larga travesía por el océano Atlántico, los marineros de tres pequeñas naves llegaron a una isla del Caribe que sus habitantes llamaban Guanahaní y que Cristóbal Colón bautizó como San Salvador. Colón era un navegante de origen genovés que había propuesto a los Reyes Católicos buscar una ruta hacia Asia navegando hacia el oeste. La reina Isabel y el rey Fernando financiaron la empresa, y las tres naves, la Pinta, la Niña y la Santa María, zarparon del puerto de Palos. Colón murió convencido de haber llegado a las Indias asiáticas, sin saber que había abierto el camino a un continente que los europeos desconocían.", "Colón realizó cuatro viajes. El primero, en 1492, le llevó a las Bahamas, Cuba y La Española. El segundo, en 1493, fue una expedición mucho mayor, con numerosas naves y colonos, que fundó asentamientos permanentes en La Española. En el tercero, hacia 1498, reconoció la costa de lo que hoy es Venezuela, y en el cuarto, a partir de 1502, exploró la costa de América Central. Cada viaje amplió el mapa que se conocía entonces. Cuando leas el diario de Colón conviene recordar que es una fuente histórica, es decir, un documento escrito por un testigo de los hechos. Un buen lector pregunta quién lo escribió, para quién, con qué propósito y qué tono emplea, porque el relato de una persona nunca es del todo neutral.", "La llegada de los europeos a América provocó lo que se llama encuentro de dos mundos. Este encuentro tuvo consecuencias muy diversas. Entre las positivas se cuentan el intercambio de productos, como la patata, el maíz o el tomate, que llegaron a Europa, y el trigo, el caballo y la vid, que llegaron a América. También se difundieron la lengua castellana y la fe cristiana, y se fundaron ciudades, universidades e instituciones. Pero hubo también consecuencias dolorosas: la propagación de enfermedades desconocidas para los pueblos americanos, los abusos en el trabajo forzado y la desaparición de comunidades enteras. Una mirada honesta no oculta ni la grandeza de la empresa ni el sufrimiento que causó.", "En medio de esos abusos se levantaron voces que defendieron a los indígenas. La más conocida es la de Bartolomé de las Casas, un sacerdote dominico del siglo XVI que había conocido de cerca la vida en las Indias. En 1511, el dominico Antonio de Montesinos predicó en La Española un sermón en el que reprochó a los colonos el trato que daban a los indígenas, y esa denuncia impresionó profundamente a Las Casas. A partir de entonces dedicó su vida a defender la dignidad de los pueblos originarios. Escribió obras como la «Brevísima relación de la destrucción de las Indias» y participó en la célebre controversia de Valladolid, hacia 1550, donde sostuvo sus ideas frente a quienes creían que los indígenas podían ser sometidos por naturaleza.", "Los argumentos de Las Casas eran sobre todo bíblicos. En primer lugar, recordaba que todos los seres humanos han sido creados a imagen de Dios, según Génesis 1:26-27, y que por tanto ninguna persona puede ser tratada como un objeto. En segundo lugar, apelaba a la enseñanza de Jesús sobre el amor al prójimo y a la regla de oro: tratar a los demás como queremos que nos traten. En tercer lugar, sostenía que la fe no puede imponerse por la fuerza, porque debe ser un acto libre de la voluntad, y que la misión que Cristo encargó en Mateo 28:19, hacer discípulos a todas las naciones, debía cumplirse con persuasión y ejemplo, no con violencia. Su influencia contribuyó a que se promulgaran las Leyes Nuevas de 1542, que intentaron limitar los abusos.", "Para realizar tu proyecto sobre el encuentro de dos mundos, recuerda que la historia exige equilibrio. Reconoce el valor de los navegantes y la importancia de los descubrimientos. Reconoce también que existieron injusticias y que hubo cristianos que las denunciaron en nombre del Evangelio. Esa actitud muestra que la conciencia moral puede corregir a los poderosos. Mateo 28:19 nos enseña que la misión cristiana tiene como horizonte a todas las naciones. Pero Cristo ordena anunciar su mensaje con amor y verdad, no mediante el sometimiento. Así comprenderás que la fe auténtica no se opone a la dignidad humana, sino que es su mejor defensa."], "glossary": [{"term": "Descubrimiento", "def": "Hallazgo de tierras o realidades que antes eran desconocidas para un pueblo; en este caso, la llegada de los europeos a América."}, {"term": "Fuente histórica", "def": "Documento u objeto del pasado que permite conocer los hechos, como un diario o una carta."}, {"term": "Indígena", "def": "Persona originaria del lugar donde vive; aquí, los pueblos que habitaban América antes de la llegada de los europeos."}, {"term": "Dominico", "def": "Miembro de la Orden de Predicadores, fundada por santo Domingo de Guzmán."}, {"term": "Dignidad", "def": "Valor propio de toda persona por ser criatura de Dios, que exige respeto."}, {"term": "Colono", "def": "Persona que se traslada a un territorio nuevo para establecerse y cultivarlo."}, {"term": "Misión", "def": "Encargo de anunciar el Evangelio y servir a otros en nombre de Cristo."}], "practice": [{"q": "Resume en pocas oraciones qué ocurrió el 12 de octubre de 1492 y quiénes hicieron posible el viaje.", "feedback": "Ese día las naves de Colón llegaron a una isla del Caribe llamada Guanahaní por sus habitantes, que Colón nombró San Salvador. El viaje fue posible porque los Reyes Católicos financiaron la expedición. Colón creyó haber llegado a Asia, pero en realidad había llegado a un continente desconocido para los europeos. Una buena respuesta incluye la fecha, el lugar y el apoyo de los reyes."}, {"q": "¿Qué preguntas debe hacerse un lector al analizar un fragmento del diario de Colón?", "feedback": "Debe preguntarse quién lo escribió, en qué fecha, con qué propósito y a quién iba dirigido. También debe observar el tono, es decir, si expresa asombro, deseo de riqueza, fe o autoridad. Con esas preguntas se reconoce que una fuente histórica ofrece un punto de vista y no toda la verdad. Para completar la visión conviene contrastarla con otras fuentes."}, {"q": "Escribe dos consecuencias positivas y dos dolorosas del encuentro de dos mundos.", "feedback": "Entre las positivas: el intercambio de alimentos como el maíz y la patata hacia Europa y el trigo y el caballo hacia América, y la difusión de la lengua y la fe. Entre las dolorosas: la propagación de enfermedades y el trabajo forzado. Es importante presentarlas con equilibrio, sin negar ninguna. La madurez histórica consiste en reconocer los bienes y los males de un mismo proceso."}, {"q": "Explica tres argumentos bíblicos de Bartolomé de las Casas y relaciónalos con Mateo 28:19.", "feedback": "Primero, todos los seres humanos son imagen de Dios, por lo que tienen dignidad. Segundo, Jesús enseñó a amar al prójimo y a tratar a los demás como queremos ser tratados. Tercero, la fe debe aceptarse libremente y no por la fuerza. Mateo 28:19 manda hacer discípulos a todas las naciones, pero un discípulo se forma con enseñanza y ejemplo, no con violencia. Por eso Las Casas defendió que la misión debía hacerse con respeto."}], "quiz": [{"q": "¿Qué llamaban los habitantes locales a la isla donde desembarcó Colón en 1492?", "opts": [{"t": "Guanahaní", "ok": true}, {"t": "La Española", "ok": false}, {"t": "Cuba", "ok": false}]}, {"q": "¿Qué es una fuente histórica, según la lectura?", "opts": [{"t": "Un documento escrito por un testigo o relacionado con los hechos del pasado", "ok": true}, {"t": "Una canción popular sin autor", "ok": false}, {"t": "Un mapa moderno", "ok": false}]}, {"q": "¿Cuál es una consecuencia dolorosa del encuentro de dos mundos?", "opts": [{"t": "La llegada del maíz a Europa", "ok": false}, {"t": "La propagación de enfermedades desconocidas para los pueblos americanos", "ok": true}, {"t": "La fundación de universidades", "ok": false}]}, {"q": "¿Qué argumento bíblico empleó Las Casas basado en Génesis 1:26-27?", "opts": [{"t": "Que los pueblos europeos eran superiores", "ok": false}, {"t": "Que los indígenas debían trabajar sin descanso", "ok": false}, {"t": "Que todo ser humano es creado a imagen de Dios y tiene dignidad", "ok": true}]}, {"q": "Según la lectura, ¿cómo debe cumplirse la misión de Mateo 28:19?", "opts": [{"t": "Con persuasión, enseñanza y ejemplo, no con violencia", "ok": true}, {"t": "Mediante la imposición por la fuerza", "ok": false}, {"t": "Evitando todo contacto con otros pueblos", "ok": false}]}], "verify": ["Cuatro viajes de Colón: 1492, 1493, 1498 y 1502 (fechas y territorios)", "Nombre indígena Guanahaní y bautizo como San Salvador", "Sermón de Montesinos en 1511 en La Española", "Controversia de Valladolid hacia 1550-1551 y Leyes Nuevas de 1542", "Título de la obra «Brevísima relación de la destrucción de las Indias»", "Origen genovés de Colón y puerto de partida (Palos)"], "timeline": [{"when": "1492", "what": "Colón llega a Guanahaní, que bautiza San Salvador."}, {"when": "1493", "what": "Segundo viaje: colonos y asentamientos en La Española."}, {"when": "1498", "what": "Tercer viaje: Colón reconoce la costa de Venezuela."}, {"when": "1502", "what": "Cuarto viaje: exploración de la costa de América Central."}, {"when": "1511", "what": "Montesinos predica en La Española contra los abusos."}, {"when": "1542", "what": "Se promulgan las Leyes Nuevas para limitar los abusos."}, {"when": "Hacia 1550", "what": "Controversia de Valladolid: Las Casas defiende a los indígenas."}], "scene": {"icons": ["⛵", "🌎", "📜"], "palette": "teal"}, "media": [{"title": "El desembarco de Colón (Dióscoro Puebla)", "what": "Representa la llegada de 1492 a Guanahaní, con las naves al fondo.", "find": "Desembarco de Colón Dióscoro Puebla", "note": "Dióscoro Puebla, 1862; dominio público"}, {"title": "Retrato de Bartolomé de las Casas", "what": "Imagen del defensor de la dignidad de los indígenas.", "find": "Bartolomé de las Casas retrato", "note": "Grabado o retrato antiguo; verificar licencia de cada versión"}, {"title": "Brevísima relación de la destrucción de las Indias (portada)", "what": "Portada de la obra de Las Casas, fuente histórica para el debate.", "find": "Brevísima relación de la destrucción de las Indias 1552 portada", "note": "Edición de 1552; dominio público"}]}, "p5:Mar": {"reading": ["La poesía es el arte de decir las cosas con belleza, ritmo y emoción. En la lengua española existe una tradición poética riquísima, y en este mes recorreremos dos de sus ramas más hermosas: el Romancero, que nació del pueblo, y la lírica del Siglo de Oro, que nació de poetas cultos. Aprender a leerlas no solo mejora nuestra sensibilidad, sino también nuestra memoria, nuestro vocabulario y nuestra capacidad de expresar lo que sentimos. Además, la poesía nos recuerda que la belleza es un don de Dios y que el lenguaje humano puede elevarse a la alabanza, como hacen los salmos de la Biblia.", "El Romancero es un conjunto de romances, es decir, poemas narrativos breves que se transmitieron de forma oral durante siglos. Muchos nacieron en la Edad Media y se cantaban en plazas, caminos y hogares. Sus temas son variados: las historias de guerra y frontera, las hazañas de héroes como el Cid, los amores desdichados, las aventuras y los hechos históricos. Un ejemplo muy conocido empieza con el verso «Abenámar, Abenámar, moro de la morería», que pertenece a un romance fronterizo. Los romances comparten algunas características: cuentan una historia con ritmo vivo, abundan los diálogos, comienzan muchas veces de forma abrupta y pasan de generación en generación con pequeñas variantes. Esa transmisión oral explica por qué no siempre conocemos a sus autores.", "Para analizar un poema necesitamos conocer las nociones básicas de métrica, que es el estudio de la medida de los versos. El verso es cada una de las líneas de un poema, y la estrofa es un grupo de versos que forma una unidad. Los versos se miden contando sílabas métricas, que no siempre coinciden con las sílabas gramaticales, porque cuando una palabra termina en vocal y la siguiente empieza por vocal pueden unirse en una sola sílaba, lo que se llama sinalefa. La rima es la repetición de sonidos al final de los versos. Es consonante cuando coinciden todos los sonidos desde la última vocal acentuada, y asonante cuando solo coinciden las vocales. Los romances tradicionales suelen estar formados por versos de ocho sílabas con rima asonante en los versos pares, y los versos impares quedan libres.", "El Siglo de Oro, que abarca aproximadamente los siglos XVI y XVII, dio a la lengua castellana una cima poética. Garcilaso de la Vega, soldado y poeta del siglo XVI, introdujo en España formas italianas como el soneto y el verso endecasílabo, de once sílabas, con una delicadeza que marcó a los poetas posteriores. Sus versos cantan el amor, la naturaleza y la fugacidad de la vida con gran musicalidad. Esta renovación estaba ligada al contacto de España con Italia, que como sabes formaba parte de los dominios de la monarquía hispánica. Gracias a esa apertura, la lengua castellana ganó nuevos ritmos y una gran capacidad para expresar pensamientos complejos.", "Fray Luis de León, que vivió en el siglo XVI, fue un religioso agustino, profesor de la Universidad de Salamanca y gran poeta. Su famosa «Oda a la vida retirada» comienza con el verso «¡Qué descansada vida / la del que huye del mundanal ruido!». En ella el poeta elogia la existencia sencilla de quien se aparta de la ambición, de la vanidad y del ruido de las ciudades para vivir con calma, cerca de la naturaleza, y con serenidad de conciencia. Lo que busca fray Luis es la paz interior, que nace de confiar en Dios y de contentarse con lo necesario. Sus versos, de siete y once sílabas combinados en estrofas de cinco versos, muestran que la belleza formal puede ir unida a una profunda reflexión moral.", "Cuando leas poemas, hazlo siempre en voz alta, porque el oído descubre el ritmo que el ojo no ve. Después subraya las palabras que más te llamen la atención, cuenta las sílabas de cada verso y marca la rima. Finalmente, pregúntate qué quiere decir el poeta y qué sentimiento transmite. Cuando escribas tu propio romance de ocho versos sobre un acontecimiento de la historia de España, procura que cada verso tenga ocho sílabas y que los versos pares rimen en asonante. El salmista pedía que las palabras de su boca y la meditación de su corazón fueran agradables a Dios. Esa es una gran enseñanza para quien escribe: que su lenguaje sea limpio, verdadero y hermoso."], "glossary": [{"term": "Romance", "def": "Poema narrativo de versos octosílabos con rima asonante en los versos pares."}, {"term": "Romancero", "def": "Conjunto de romances, tradicionales o de autor, transmitidos oralmente o por escrito."}, {"term": "Verso", "def": "Cada una de las líneas de un poema, sujeta a una medida y un ritmo."}, {"term": "Estrofa", "def": "Grupo de versos que forman una unidad dentro de un poema."}, {"term": "Rima asonante", "def": "Coincidencia de las vocales finales de dos versos desde la última vocal acentuada."}, {"term": "Rima consonante", "def": "Coincidencia de todos los sonidos finales de dos versos desde la última vocal acentuada."}, {"term": "Sinalefa", "def": "Unión en una sola sílaba métrica de la vocal final de una palabra con la vocal inicial de la siguiente."}, {"term": "Oda", "def": "Poema lírico de tono elevado que expresa admiración o reflexión sobre un asunto."}], "practice": [{"q": "Explica qué es un romance y menciona tres características del Romancero.", "feedback": "Un romance es un poema narrativo breve, de versos de ocho sílabas con rima asonante en los versos pares. Entre las características del Romancero están la transmisión oral durante siglos, el ritmo vivo con abundancia de diálogos y los temas de guerra, hazañas y amores. Muchos romances no tienen autor conocido porque pasaron de generación en generación con variantes."}, {"q": "Cuenta las sílabas métricas del verso «¡Qué descansada vida!» y explica qué es la rima asonante.", "feedback": "El verso se mide así: Qué-des-can-sa-da-vi-da, que son siete sílabas. La rima asonante es la coincidencia de las vocales finales de dos versos a partir de la última vocal acentuada, sin que coincidan las consonantes. Por ejemplo, «camino» y «amigo» tienen asonancia en i-o. Es importante diferenciarla de la rima consonante, que exige que coincidan todos los sonidos."}, {"q": "¿Qué busca el poeta en la «Oda a la vida retirada» de fray Luis de León?", "feedback": "El poeta busca la paz interior que se alcanza al alejarse de la ambición y de la vanidad. Elogia la vida sencilla, cercana a la naturaleza, con la conciencia en calma. Esta paz está relacionada con confiar en Dios y contentarse con lo necesario. El poema une belleza formal y enseñanza moral."}, {"q": "Escribe dos versos de ocho sílabas sobre un hecho histórico de España y señala dónde pondrías la rima.", "feedback": "Un ejemplo posible es: «Por la mar partió la flota / hacia tierras de Occidente». Los dos versos tienen ocho sílabas y la rima asonante estaría en el segundo verso, en las vocales e-e. La clave es contar con cuidado las sílabas, teniendo en cuenta las sinalefas, y comprobar el ritmo leyendo en voz alta."}], "quiz": [{"q": "¿Cuántas sílabas tienen normalmente los versos del romance tradicional?", "opts": [{"t": "Ocho", "ok": true}, {"t": "Once", "ok": false}, {"t": "Catorce", "ok": false}]}, {"q": "¿Cómo se transmitieron los romances durante siglos?", "opts": [{"t": "Solo por escrito en libros de lujo", "ok": false}, {"t": "De forma oral, de generación en generación", "ok": true}, {"t": "Exclusivamente en la universidad", "ok": false}]}, {"q": "¿Qué aportó Garcilaso de la Vega a la poesía española?", "opts": [{"t": "Introdujo formas italianas como el soneto y el endecasílabo", "ok": true}, {"t": "Inventó el romance", "ok": false}, {"t": "Prohibió la rima", "ok": false}]}, {"q": "¿Qué es la rima asonante?", "opts": [{"t": "Coincidencia de todos los sonidos finales", "ok": false}, {"t": "Ausencia total de rima", "ok": false}, {"t": "Coincidencia solo de las vocales finales desde la última acentuada", "ok": true}]}, {"q": "¿Qué busca fray Luis de León en su «Oda a la vida retirada»?", "opts": [{"t": "La fama y el poder en la corte", "ok": false}, {"t": "La paz interior alejada de la ambición y la vanidad", "ok": true}, {"t": "La riqueza de los grandes mercaderes", "ok": false}]}], "verify": ["Verso inicial «Abenámar, Abenámar, moro de la morería» (romance fronterizo)", "Verso «¡Qué descansada vida / la del que huye del mundanal ruido!» (dominio público)", "Descripción métrica de la lira (versos de 7 y 11 sílabas en estrofas de cinco)", "Fray Luis de León: agustino, profesor en Salamanca, siglo XVI", "Garcilaso de la Vega: introducción del soneto y del endecasílabo italiano", "Delimitación del Siglo de Oro (siglos XVI y XVII, aproximada)"], "timeline": [{"when": "Paso 1", "what": "Lee el poema en voz alta para oír su ritmo."}, {"when": "Paso 2", "what": "Subraya las palabras que más te llamen la atención."}, {"when": "Paso 3", "what": "Cuenta las sílabas métricas de cada verso."}, {"when": "Paso 4", "what": "Marca la rima: consonante o asonante."}, {"when": "Paso 5", "what": "Pregúntate qué quiere decir el poeta y qué siente."}, {"when": "Paso 6", "what": "Escribe tu romance de ocho versos con rima asonante en los pares."}], "scene": {"icons": ["📖", "🪶", "🎶"], "palette": "rose"}, "media": [{"title": "Retrato de Garcilaso de la Vega", "what": "Muestra al soldado y poeta que introdujo el soneto y el endecasílabo.", "find": "Garcilaso de la Vega retrato Pacheco", "note": "Francisco Pacheco, siglo XVII; dominio público"}, {"title": "Retrato de fray Luis de León", "what": "Imagen del poeta agustino, profesor de la Universidad de Salamanca.", "find": "Fray Luis de León retrato Pacheco", "note": "Francisco Pacheco, siglo XVII; dominio público"}, {"title": "Cancionero de romances (Amberes, hacia 1550)", "what": "Portada de una antigua colección impresa de romances tradicionales.", "find": "Cancionero de romances Amberes portada", "note": "Impreso del siglo XVI; verificar licencia de la digitalización"}]}, "p5:Abr": {"reading": ["Se llama Siglo de Oro al periodo en que las letras y las artes españolas alcanzaron su mayor esplendor, entre mediados del siglo XVI y gran parte del siglo XVII, aunque los historiadores no lo fechan con exactitud. En esos años vivieron Miguel de Cervantes, autor del «Quijote», cuya primera parte apareció en 1605 y la segunda en 1615, Lope de Vega, Calderón de la Barca, Velázquez y el pintor El Greco, además de teólogos y juristas de la Universidad de Salamanca. La monarquía hispánica era entonces una potencia mundial, con territorios en Europa, América y Asia, y ese contacto con tantas culturas alimentó un florecimiento sin igual. Sin embargo, junto a la grandeza hubo también problemas económicos, guerras y tensiones religiosas que lo hacen un periodo de luces y sombras.", "Una de las instituciones más discutidas de la época es la Inquisición. Los Reyes Católicos la establecieron en 1478 como un tribunal de la Iglesia bajo autoridad real, con el fin de vigilar la ortodoxia de la fe, especialmente entre los conversos, es decir, personas que habían abandonado el judaísmo o el islam para hacerse cristianas. Los inquisidores investigaban acusaciones de herejía, y el procedimiento incluía interrogatorios, sentencias y, en casos graves, penas severas, entre ellas la entrega al poder civil para la ejecución. La institución perduró siglos y fue suprimida definitivamente en el siglo XIX. Los historiadores discuten hoy el número de víctimas y la gravedad de sus procedimientos, y por eso conviene distinguir entre hechos comprobados y exageraciones.", "Para estudiar la Inquisición con honestidad conviene separar los hechos de las interpretaciones. Un hecho es algo que ocurrió y puede probarse con documentos, como la fecha de su fundación o la existencia de procesos y sentencias. Una interpretación es una explicación o una valoración de esos hechos, y puede variar según quién la escribe. Durante siglos circuló una imagen exagerada y a veces falsa de España, creada por sus enemigos políticos, que se conoce como leyenda negra. Pero rechazar las exageraciones no significa defender cuanto ocurrió. Un cristiano honesto reconoce que se cometieron injusticias, porque las personas fueron juzgadas y castigadas por sus creencias y no solo por sus actos, y que ello contradice el espíritu de libertad con que Cristo invita a creer.", "La pregunta de fondo es muy importante: ¿puede un Estado cristiano actuar contra la conciencia de sus ciudadanos? La Biblia ofrece una respuesta clara en Hechos 5:29. Cuando las autoridades de Jerusalén prohibieron a los apóstoles predicar, Pedro respondió: «Es necesario obedecer a Dios antes que a los hombres». Este versículo establece que la conciencia ante Dios está por encima de cualquier mandato humano. Por eso, un gobierno que obliga a creer o castiga a quien piensa distinto invade un terreno que pertenece únicamente a Dios. En el mismo siglo XVI, teólogos españoles como Francisco de Vitoria, de la Universidad de Salamanca, defendían derechos universales de las personas, lo que muestra que dentro del mundo cristiano hubo voces que apuntaban hacia una mayor justicia.", "El arte del Siglo de Oro fue muchas veces un reflejo de la fe. El Greco, que nació en la isla de Creta y se estableció en Toledo, pintó hacia 1586 «El entierro del conde de Orgaz», un cuadro de gran tamaño que se conserva en la iglesia de Santo Tomé. La obra se divide en dos zonas. En la inferior, caballeros toledanos de rostros muy expresivos rodean el cuerpo del difunto, mientras dos santos lo depositan en la tumba. En la superior, el cielo se abre y aparecen Cristo, la Virgen y los santos recibiendo el alma del conde. El mensaje es que la muerte no tiene la última palabra y que la vida terrena se ordena hacia la eternidad. Las figuras alargadas y los colores intensos buscan expresar lo espiritual.", "Al preparar tu trabajo sobre el Siglo de Oro, recuerda el título propuesto: grandeza y sombras. La grandeza se ve en la literatura, la pintura, la teología y la proyección de España en el mundo. Las sombras se ven en las guerras, la crisis económica y la intolerancia religiosa. Los dos lados son verdaderos, y estudiar ambos nos hace más sabios. Un historiador cristiano busca la verdad sin miedo, porque cree que la verdad nos hace libres. Y, ante cada autoridad humana, recuerda la lección de Pedro: es necesario obedecer a Dios antes que a los hombres, y hacerlo con respeto y mansedumbre."], "glossary": [{"term": "Siglo de Oro", "def": "Periodo de máximo esplendor de las letras y las artes españolas, entre los siglos XVI y XVII."}, {"term": "Inquisición", "def": "Tribunal eclesiástico, bajo autoridad real en España, que investigaba delitos contra la fe."}, {"term": "Converso", "def": "Persona que abandonó el judaísmo o el islam para hacerse cristiana."}, {"term": "Herejía", "def": "Doctrina contraria a las enseñanzas fundamentales de la fe de la Iglesia."}, {"term": "Leyenda negra", "def": "Imagen exagerada y negativa de España difundida por sus rivales durante siglos."}, {"term": "Conciencia", "def": "Capacidad interior de distinguir el bien del mal y de responder ante Dios por los propios actos."}, {"term": "Interpretación", "def": "Explicación o valoración que una persona hace de unos hechos históricos."}], "practice": [{"q": "Explica qué fue el Siglo de Oro y menciona al menos tres figuras de esa época.", "feedback": "El Siglo de Oro fue el periodo de mayor esplendor literario y artístico de España, entre mediados del siglo XVI y el XVII. Entre sus figuras están Cervantes, autor del Quijote, Lope de Vega, Calderón de la Barca, Velázquez y El Greco. Fue una época de grandeza cultural, aunque también de crisis económica y guerras. Una buena respuesta incluye esa doble cara."}, {"q": "Distingue un hecho de una interpretación en el estudio de la Inquisición y da un ejemplo de cada uno.", "feedback": "Un hecho es algo comprobable, como que la Inquisición se estableció en 1478 o que realizó procesos. Una interpretación es una valoración, por ejemplo decir que fue siempre cruel o que fue una institución normal para su época. Separar ambas cosas es esencial para no repetir exageraciones ni justificar injusticias. Las interpretaciones deben apoyarse siempre en pruebas."}, {"q": "¿Qué enseña Hechos 5:29 sobre los límites del poder humano? Aplícalo a la pregunta del debate familiar.", "feedback": "Hechos 5:29 enseña que la conciencia ante Dios está por encima de cualquier orden humana contraria a Su voluntad. Aplicado al debate, un Estado cristiano no debería obligar a creer ni castigar la conciencia de sus ciudadanos, porque la fe debe nacer libremente. El gobierno puede mantener el orden y la justicia, pero no sustituir a Dios en el terreno interior de cada persona."}, {"q": "Describe el mensaje de «El entierro del conde de Orgaz» de El Greco.", "feedback": "El cuadro tiene dos zonas: abajo, los caballeros y los santos que entierran al conde; arriba, el cielo abierto donde Cristo y los santos reciben su alma. Transmite que la muerte no es el final y que la vida terrena se orienta a la eternidad. Las figuras alargadas y los colores intensos refuerzan la expresión espiritual de la escena."}], "quiz": [{"q": "¿Cuándo se estableció la Inquisición española según la lectura?", "opts": [{"t": "En 1478", "ok": true}, {"t": "En 1605", "ok": false}, {"t": "En 1834", "ok": false}]}, {"q": "¿Qué es la leyenda negra?", "opts": [{"t": "Un poema del Siglo de Oro", "ok": false}, {"t": "Una imagen exagerada y negativa de España difundida por sus rivales", "ok": true}, {"t": "Un cuadro de El Greco", "ok": false}]}, {"q": "¿Qué afirma Hechos 5:29?", "opts": [{"t": "Que hay que obedecer siempre a las autoridades humanas", "ok": false}, {"t": "Que la fe debe imponerse por la fuerza", "ok": false}, {"t": "Que es necesario obedecer a Dios antes que a los hombres", "ok": true}]}, {"q": "¿Dónde pintó y estableció su obra El Greco, según la lectura?", "opts": [{"t": "En Toledo", "ok": true}, {"t": "En Sevilla", "ok": false}, {"t": "En Granada", "ok": false}]}, {"q": "¿Qué mensaje transmite «El entierro del conde de Orgaz»?", "opts": [{"t": "Que la muerte es el final de todo", "ok": false}, {"t": "Que la vida terrena se orienta hacia la eternidad", "ok": true}, {"t": "Que los nobles son superiores a los santos", "ok": false}]}], "verify": ["Fundación de la Inquisición española en 1478 y supresión definitiva en el siglo XIX (1834)", "Fechas del «Quijote»: 1605 y 1615", "«El entierro del conde de Orgaz»: hacia 1586, iglesia de Santo Tomé, Toledo", "El Greco nacido en Creta", "Papel de Francisco de Vitoria en la Escuela de Salamanca", "Valoración del número de víctimas de la Inquisición (debate historiográfico: evitar cifras)"], "timeline": [{"when": "1478", "what": "Los Reyes Católicos establecen la Inquisición."}, {"when": "Siglos XVI-XVII", "what": "Esplendor de las letras y las artes: el Siglo de Oro."}, {"when": "Hacia 1586", "what": "El Greco pinta «El entierro del conde de Orgaz» en Toledo."}, {"when": "1605", "what": "Aparece la primera parte del «Quijote»."}, {"when": "1615", "what": "Aparece la segunda parte del «Quijote»."}, {"when": "Siglo XIX", "what": "La Inquisición es suprimida definitivamente."}], "scene": {"icons": ["🎨", "📚", "⛪"], "palette": "amber"}, "media": [{"title": "El entierro del conde de Orgaz (El Greco)", "what": "Obra de dos zonas, tierra y cielo, que expresa la fe del Siglo de Oro.", "find": "El entierro del conde de Orgaz El Greco Santo Tomé", "note": "El Greco, hacia 1586; dominio público"}, {"title": "Retrato de Miguel de Cervantes (atribuido a Jáuregui)", "what": "Imagen tradicional del autor del «Quijote».", "find": "Retrato de Cervantes Jáuregui", "note": "Atribuido a Juan de Jáuregui, siglo XVII; verificar licencia"}, {"title": "Portada de «El ingenioso hidalgo don Quijote de la Mancha» (1605)", "what": "Portada de la primera edición, ejemplo del esplendor literario.", "find": "Don Quijote 1605 primera edición portada", "note": "Edición de 1605; dominio público"}]}, "p5:May": {"reading": ["La economía estudia cómo las personas producen, reparten y usan los bienes y servicios para vivir. Todos formamos parte de ella: cuando un agricultor siembra, un artesano fabrica o un maestro enseña, está contribuyendo al bienestar de su comunidad. Para estudiarla mejor, los geógrafos agrupan las actividades económicas en tres grandes sectores. Comprender esta clasificación te ayudará a leer mapas económicos y a analizar la actividad principal de tu comunidad autónoma. Además, desde la fe cristiana, el trabajo es una vocación: Dios puso al ser humano en el jardín para que lo cultivara y lo guardara, y por eso el trabajo honrado es una forma de servir a Dios y a los demás.", "El sector primario obtiene los recursos directamente de la naturaleza. Incluye la agricultura, la ganadería, la pesca, la explotación forestal y la minería. España destaca en el cultivo del olivo, y su aceite de oliva es muy conocido en todo el mundo. También produce vino, cereales, frutas y hortalizas, y tiene una importante actividad pesquera en las costas del Atlántico y del Cantábrico. El sector secundario transforma esas materias primas en productos elaborados. Pertenecen a él la industria alimentaria, la construcción, la fabricación de automóviles y la industria química. Por último, el sector terciario ofrece servicios, como el comercio, la educación, la sanidad, el transporte, las finanzas y el turismo. En España y en la mayoría de los países desarrollados, este último sector es el que emplea a más personas.", "Los recursos naturales de España varían de una región a otra, porque el clima y el relieve son muy distintos. En el norte, más lluvioso, abundan los pastos y la ganadería, y en Galicia la pesca ocupa un lugar central. En la zona mediterránea, con clima más cálido, se cultivan cítricos y hortalizas, y en el valle del Ebro y en La Rioja destacan la fruta y el vino. En el interior de la meseta predominan los cereales y las dehesas, donde se cría ganado. El sur de la península, especialmente Andalucía, es una gran productora de olivar y de productos hortícolas. Históricamente, regiones como Asturias se asociaron a la minería del carbón. Estas diferencias nos enseñan que cada comunidad tiene unos dones propios que puede administrar con sabiduría.", "El turismo es una de las actividades más importantes de la economía española. Millones de visitantes llegan cada año atraídos por el clima, las playas, el patrimonio histórico, la gastronomía y la cultura. El turismo crea empleos en hoteles, restaurantes, transportes y comercios, y da a conocer la lengua y las costumbres del país. Pero también plantea retos. Cuando el número de visitantes es excesivo en algunas ciudades, puede encarecer la vivienda, saturar los servicios y alterar la vida de los vecinos. Además, depender de una sola actividad hace a la economía vulnerable si ocurre una crisis. Un turismo sostenible busca equilibrar los beneficios económicos con el cuidado del entorno y el bienestar de quienes residen allí.", "La Biblia ofrece una enseñanza muy valiosa sobre el trabajo y la riqueza. En Deuteronomio 8:18, Moisés recuerda al pueblo de Israel: «Acuérdate del Señor tu Dios, porque Él te da el poder para hacer las riquezas». Esto significa que la capacidad de trabajar, de crear y de producir es un don de Dios y no un mérito exclusivo nuestro. De ahí se derivan varias actitudes: la gratitud por lo que recibimos, la honradez en el trabajo, la generosidad con los necesitados y la prudencia para no depender de la riqueza. También recordamos que somos administradores de la creación, y que los recursos naturales deben usarse con responsabilidad para que lleguen a las próximas generaciones.", "Para realizar tu infografía económica, empieza investigando cuál es la actividad principal de tu comunidad autónoma y a qué sector pertenece. Busca datos fiables en fuentes oficiales o en publicaciones de confianza, y evita copiar cifras sin comprobarlas. Después organiza la información con claridad: usa colores distintos para cada sector, símbolos sencillos para los productos y textos breves que expliquen lo esencial. Una buena infografía no abruma al lector, sino que lo guía. Por último, añade una reflexión personal sobre cómo puede tu comunidad aprovechar sus recursos con justicia y cuidado. Así combinarás la investigación geográfica con la mirada de la fe sobre el trabajo y las riquezas."], "glossary": [{"term": "Sector primario", "def": "Conjunto de actividades que obtienen recursos directamente de la naturaleza, como la agricultura o la pesca."}, {"term": "Sector secundario", "def": "Actividades que transforman las materias primas en productos elaborados, como la industria."}, {"term": "Sector terciario", "def": "Actividades de servicios, como el comercio, la educación, el transporte y el turismo."}, {"term": "Materia prima", "def": "Recurso natural que se transforma para fabricar un producto."}, {"term": "Recurso natural", "def": "Elemento de la naturaleza, como el agua, el suelo o los minerales, que el ser humano aprovecha."}, {"term": "Turismo sostenible", "def": "Forma de turismo que busca equilibrar el beneficio económico con el cuidado del entorno y de los vecinos."}, {"term": "Comunidad autónoma", "def": "Cada una de las grandes divisiones territoriales con gobierno propio en que se organiza España."}, {"term": "Infografía", "def": "Representación visual que combina imágenes, símbolos y textos breves para explicar información."}], "practice": [{"q": "Explica los tres sectores económicos y pon un ejemplo de cada uno.", "feedback": "El sector primario obtiene recursos de la naturaleza, por ejemplo la agricultura del olivo o la pesca. El secundario transforma esas materias primas, por ejemplo la industria alimentaria que fabrica aceite envasado o conservas. El terciario ofrece servicios, como el comercio, la educación o el turismo. Es importante ver que los tres sectores dependen unos de otros: sin materias primas no hay industria, y sin servicios no llegan los productos al consumidor."}, {"q": "Elige una región de España, describe un recurso o actividad destacada y explica por qué se da allí.", "feedback": "Un ejemplo: en Andalucía abunda el olivar porque el clima cálido y seco favorece este cultivo. Otro ejemplo es Galicia, donde la costa atlántica y el mar favorecen la pesca. La respuesta debe relacionar la actividad con el clima, el relieve o la historia del lugar. Así se aprende que la geografía física condiciona la economía."}, {"q": "Escribe una ventaja y un reto del turismo masivo para una ciudad.", "feedback": "Una ventaja es la creación de empleo en hoteles, restaurantes y comercios, junto con la difusión de la cultura. Un reto es que el exceso de visitantes puede encarecer la vivienda, saturar los servicios y alterar la vida de los vecinos. Un turismo sostenible busca equilibrar ambos aspectos. En un debate conviene aportar ejemplos concretos y escuchar los argumentos contrarios."}, {"q": "¿Qué enseña Deuteronomio 8:18 sobre la riqueza y qué actitudes se derivan de ello?", "feedback": "Enseña que la capacidad de producir riqueza es un don de Dios y no solo un mérito propio. De ahí se derivan la gratitud, la honradez en el trabajo, la generosidad con los necesitados y la prudencia para no depender del dinero. También recuerda que somos administradores de los recursos de la creación y que debemos usarlos con responsabilidad."}], "quiz": [{"q": "¿A qué sector pertenece la pesca?", "opts": [{"t": "Al sector terciario", "ok": false}, {"t": "Al sector primario", "ok": true}, {"t": "Al sector secundario", "ok": false}]}, {"q": "¿Qué actividad pertenece al sector secundario?", "opts": [{"t": "La industria que transforma materias primas en productos", "ok": true}, {"t": "La enseñanza en una escuela", "ok": false}, {"t": "El cultivo del olivo", "ok": false}]}, {"q": "¿Cuál es un reto del turismo masivo según la lectura?", "opts": [{"t": "La disminución de los empleos", "ok": false}, {"t": "La falta total de visitantes", "ok": false}, {"t": "El encarecimiento de la vivienda y la saturación de servicios", "ok": true}]}, {"q": "¿Qué enseña Deuteronomio 8:18?", "opts": [{"t": "Que la riqueza es solo fruto del esfuerzo propio", "ok": false}, {"t": "Que la capacidad de producir riqueza es un don de Dios", "ok": true}, {"t": "Que se debe rechazar todo trabajo", "ok": false}]}, {"q": "¿Qué sector emplea a más personas en España y en los países desarrollados?", "opts": [{"t": "El sector primario", "ok": false}, {"t": "El sector terciario", "ok": true}, {"t": "El sector minero", "ok": false}]}], "verify": ["Productos asociados a cada región (olivar en Andalucía, pesca en Galicia, vino en La Rioja, cítricos en el Mediterráneo)", "Afirmación de que el sector terciario es el que más empleo concentra en España", "Minería del carbón en Asturias como asociación histórica", "Cita de Deuteronomio 8:18 en la versión empleada por el centro", "Datos concretos de la comunidad autónoma de cada alumno (fuentes oficiales)"], "timeline": [{"when": "Paso 1", "what": "Investiga la actividad principal de tu comunidad autónoma."}, {"when": "Paso 2", "what": "Decide a qué sector pertenece: primario, secundario o terciario."}, {"when": "Paso 3", "what": "Busca datos fiables en fuentes oficiales y compruébalos."}, {"when": "Paso 4", "what": "Usa un color distinto para cada sector."}, {"when": "Paso 5", "what": "Añade símbolos sencillos y textos breves."}, {"when": "Paso 6", "what": "Escribe una reflexión sobre usar los recursos con justicia."}], "scene": {"icons": ["🫒", "🏭", "🏖️"], "palette": "green"}, "media": [{"title": "Olivar andaluz", "what": "Paisaje de olivos que ilustra el sector primario y el aceite de oliva.", "find": "olive grove Andalusia Jaén", "note": "Fotografía moderna; verificar licencia"}, {"title": "Dehesa de la meseta", "what": "Paisaje de encinas y ganado típico del interior.", "find": "dehesa Extremadura encinas ganado", "note": "Fotografía moderna; verificar licencia"}, {"title": "Playa y turismo en la costa mediterránea", "what": "Ilustra el sector terciario y el turismo.", "find": "Costa Blanca beach tourism Spain", "note": "Fotografía moderna; verificar licencia"}], "map": {"region": "iberia", "markers": [{"name": "Galicia (pesca)", "lat": 42.8, "lon": -8.0, "kind": "site"}, {"name": "Asturias (minería del carbón)", "lat": 43.3, "lon": -5.9, "kind": "site"}, {"name": "La Rioja (vino)", "lat": 42.3, "lon": -2.5, "kind": "site"}, {"name": "Valle del Ebro (fruta)", "lat": 41.6, "lon": -0.9, "kind": "river"}, {"name": "Andalucía (olivar)", "lat": 37.6, "lon": -4.5, "kind": "site"}]}}, "p5:Jun": {"reading": ["El español es una de las lenguas más habladas del planeta. Nació en la península ibérica a partir del latín que hablaban los romanos, y se desarrolló en el reino de Castilla, de donde recibe el nombre de castellano. Con el tiempo, gracias a la expansión de la monarquía hispánica, esa lengua viajó a América, a Filipinas y a otros lugares. Hoy la hablan cientos de millones de personas en todos los continentes, y es lengua oficial en cerca de veinte países, entre ellos España, México, Argentina, Colombia, Perú, Chile y Guinea Ecuatorial. Esta extensión es un legado histórico enorme y también una responsabilidad, porque quien posee un don debe usarlo para bendecir a otros.", "Un momento importante en la historia de nuestra lengua fue el año 1492, cuando Antonio de Nebrija publicó su «Gramática de la lengua castellana», la primera gramática de una lengua romance. Nebrija comprendió que una lengua necesitaba reglas claras para enseñarse y conservarse. Siglos después, en 1713, se fundó la Real Academia Española con el propósito de cuidar la lengua, y desde entonces ha colaborado con las academias de los países hispanohablantes para mantener la unidad del idioma. Esta tarea compartida explica por qué una persona de Madrid puede entenderse con otra de Bogotá o de Buenos Aires, a pesar de la enorme distancia.", "Sin embargo, el español no se habla de la misma manera en todas partes. Existen variedades, que se diferencian en la pronunciación, el vocabulario y algunas formas gramaticales. Entre el español peninsular y el hispanoamericano hay algunas diferencias bien conocidas. En gran parte de Hispanoamérica y en Canarias se emplea el seseo, es decir, se pronuncia igual la «s» y la «z». En España se usa el pronombre «vosotros» para dirigirse a varias personas de confianza, mientras que en América se emplea «ustedes». En algunos países, como Argentina, se usa el voseo, que consiste en decir «vos» en lugar de «tú». También cambian algunas palabras: lo que en España es un «ordenador», en México es una «computadora»; un «coche» es un «carro» en varios países; y el «zumo» es el «jugo».", "Estas diferencias no son errores ni defectos, sino riqueza. Todas las variedades son legítimas cuando respetan las normas básicas de la lengua, y ninguna es superior a las demás. Lo importante es comprender que hablamos un idioma común, con una gramática y una ortografía compartidas. Por eso, al escribir una carta a un estudiante de otro país hispanohablante, conviene usar un lenguaje claro y cuidar el respeto. También ayuda tener curiosidad por sus palabras y costumbres. Escribir una carta bien redactada exige estructura: un saludo, una introducción en la que te presentas, un desarrollo con preguntas y relatos sobre tu vida, y una despedida cordial.", "El español ha sido también una lengua de fe. Con ella se predicó el Evangelio y se escribieron obras de piedad en España y en América. En 1569, Casiodoro de Reina publicó la primera traducción completa de la Biblia al castellano a partir de las lenguas originales, conocida como la «Biblia del Oso». Más tarde fue revisada por Cipriano de Valera y dio origen a la versión Reina-Valera, que muchos hispanohablantes leen hasta hoy. Además, escritores como santa Teresa de Jesús y san Juan de la Cruz expresaron su vida espiritual en un castellano de gran belleza. De esta manera, la lengua se convirtió en un instrumento para anunciar la Palabra de Dios y para cultivar el alma.", "El profeta Sofonías anunció que Dios devolvería a los pueblos una «lengua pura», para que todos invocaran el nombre del Señor y le sirvieran de común consentimiento. Aunque ese pasaje tiene su cumplimiento pleno en la obra de Dios, nos inspira a pensar que el lenguaje puede ser purificado y puesto al servicio del bien. Quien habla español tiene hoy una puerta abierta a millones de personas. Si cuidamos nuestra manera de hablar, si evitamos la mentira, la burla y la vulgaridad, y si usamos las palabras para edificar, el castellano se convierte en una herramienta de misión. Tu mapa del español y tu carta serán una pequeña muestra de esa tarea."], "glossary": [{"term": "Hispanohablante", "def": "Persona que tiene el español como lengua materna o que lo habla habitualmente."}, {"term": "Lengua oficial", "def": "Idioma reconocido por las leyes de un país para su administración y su enseñanza."}, {"term": "Variedad lingüística", "def": "Forma particular de hablar una lengua en un lugar o grupo, con rasgos propios de pronunciación y vocabulario."}, {"term": "Seseo", "def": "Pronunciación de la «z» y la «c» ante e, i como una «s»."}, {"term": "Voseo", "def": "Uso del pronombre «vos» en lugar de «tú» en algunas regiones de Hispanoamérica."}, {"term": "Gramática", "def": "Conjunto de normas que regulan el uso correcto de una lengua."}, {"term": "Real Academia Española", "def": "Institución fundada en 1713 para cuidar la unidad y la corrección del idioma."}], "practice": [{"q": "Explica de dónde procede el español y cómo llegó a hablarse en tantos países.", "feedback": "El español procede del latín hablado en la península ibérica y se desarrolló como castellano en el reino de Castilla. Con la expansión de la monarquía hispánica llegó a América, a Filipinas y a otros lugares, y ahí echó raíces. Hoy es lengua oficial en cerca de veinte países. Una buena respuesta menciona el origen latino y el papel de la historia en su difusión."}, {"q": "Escribe tres diferencias entre el español de España y el de Hispanoamérica y explica por qué no son errores.", "feedback": "Algunas diferencias son el uso de «vosotros» en España frente a «ustedes» en América, el voseo en regiones como Argentina y el vocabulario, como «ordenador» y «computadora» o «coche» y «carro». No son errores porque cada variedad respeta las reglas básicas de la lengua común y es parte de su riqueza. Ninguna variedad es superior a las demás."}, {"q": "¿Qué partes debe tener una carta dirigida a un estudiante de otro país hispanohablante?", "feedback": "Debe tener un saludo, una introducción en la que te presentas, un desarrollo con relatos y preguntas sobre la vida cotidiana y una despedida cordial. Conviene escribir con claridad, cuidar la ortografía y mostrar curiosidad por la cultura de la otra persona. Así la carta cumple su función de acercar a dos personas separadas por la distancia."}, {"q": "¿Cómo puede el castellano convertirse en una herramienta de misión? Relaciona tu respuesta con Sofonías 3:9.", "feedback": "El castellano permite comunicar el Evangelio a millones de personas, como ocurrió con la Biblia de Casiodoro de Reina. Sofonías 3:9 habla de una lengua pura que sirve para invocar el nombre del Señor, y eso nos anima a cuidar nuestras palabras, evitando la mentira y la burla. Cuando hablamos con verdad y amor, la lengua se convierte en un medio de bendición para otros."}], "quiz": [{"q": "¿De qué lengua procede el español?", "opts": [{"t": "Del griego", "ok": false}, {"t": "Del latín", "ok": true}, {"t": "Del francés", "ok": false}]}, {"q": "¿Qué publicó Antonio de Nebrija en 1492?", "opts": [{"t": "Una traducción de la Biblia", "ok": false}, {"t": "La primera gramática de la lengua castellana", "ok": true}, {"t": "El Quijote", "ok": false}]}, {"q": "¿Qué pronombre se usa en gran parte de Hispanoamérica para dirigirse a varias personas?", "opts": [{"t": "Vosotros", "ok": false}, {"t": "Ustedes", "ok": true}, {"t": "Nosotros", "ok": false}]}, {"q": "¿Qué es la «Biblia del Oso»?", "opts": [{"t": "La primera traducción completa de la Biblia al castellano, de Casiodoro de Reina", "ok": true}, {"t": "Un libro de poemas de fray Luis de León", "ok": false}, {"t": "Una gramática de Nebrija", "ok": false}]}, {"q": "Según la lectura, ¿cómo deben valorarse las variedades del español?", "opts": [{"t": "Como errores que hay que corregir", "ok": false}, {"t": "Como riqueza legítima de una lengua común", "ok": true}, {"t": "Como prueba de que no existe un idioma común", "ok": false}]}], "verify": ["Número de hispanohablantes y de países con español oficial: la entrada indica 580 millones y 22 países; las fuentes habituales varían (en torno a 20-21 países); se evitó la cifra exacta", "Gramática de Nebrija, 1492", "Fundación de la Real Academia Española en 1713", "Biblia del Oso, 1569, Casiodoro de Reina; revisión de Cipriano de Valera", "Seseo en Canarias y gran parte de Hispanoamérica", "Cita de Sofonías 3:9 en la versión empleada por el centro"], "timeline": [{"when": "Época romana", "what": "El latín de los romanos es el origen del español."}, {"when": "Edad Media", "what": "El castellano se desarrolla en el reino de Castilla."}, {"when": "1492", "what": "Nebrija publica la primera gramática de una lengua romance."}, {"when": "1569", "what": "Casiodoro de Reina publica la «Biblia del Oso»."}, {"when": "1713", "what": "Se funda la Real Academia Española."}, {"when": "Hoy", "what": "Cientos de millones hablan español en todos los continentes."}], "scene": {"icons": ["🗣️", "✉️", "🌍"], "palette": "blue"}, "media": [{"title": "Gramática de la lengua castellana (Nebrija, 1492)", "what": "Portada de la primera gramática de una lengua romance.", "find": "Gramática de la lengua castellana Nebrija 1492", "note": "Edición antigua; verificar licencia de la digitalización"}, {"title": "Biblia del Oso (1569), portada", "what": "Primera traducción completa de la Biblia al castellano.", "find": "Biblia del Oso 1569 portada Casiodoro de Reina", "note": "Impreso de 1569; dominio público"}, {"title": "Mapa de países de habla hispana", "what": "Muestra dónde es lengua oficial el español.", "find": "Spanish language world map official", "note": "Mapa moderno; verificar licencia"}]}, "p5:Jul": {"reading": ["Hemos llegado al final de un curso en el que viajamos por la historia, por el mapa y por la lengua de España. Este proyecto final te invita a reunir todo lo aprendido y a responder a una pregunta importante: ¿qué significa ser español y cristiano en un mundo globalizado? Globalizado quiere decir que hoy los países están muy conectados por el comercio, los viajes, los medios de comunicación e internet. Una persona puede hablar con alguien al otro lado del planeta en un instante. Esa cercanía ofrece grandes oportunidades, pero también el riesgo de olvidar nuestras raíces y de pensar que todo da lo mismo. Por eso conviene mirar hacia atrás, con serenidad, para saber quiénes somos y hacia dónde vamos.", "Repasemos lo estudiado. En Historia vimos cómo Carlos I y Felipe II gobernaron un imperio inmenso, cómo Colón abrió el camino hacia un nuevo continente y cómo Bartolomé de las Casas defendió la dignidad de los pueblos indígenas en nombre de la Biblia. Estudiamos también el Siglo de Oro, con su grandeza artística y sus sombras. En Geografía situamos a España en Europa, conocimos a sus vecinos y descubrimos la riqueza de su economía. En Lengua aprendimos a argumentar con orden, a leer poesía clásica y a valorar el español como lengua de millones de personas. Estas piezas no están separadas. Forman un conjunto en el que cada una ilumina a las demás, y hacer un mapa mental te ayudará a verlo.", "Un mapa mental es un esquema que parte de una idea central y se ramifica en ideas secundarias. En el centro puedes escribir «España cristiana en el mundo» y de él pueden partir tres ramas: historia, geografía y lengua. En cada rama añade los hechos más importantes y conecta con líneas las ideas que se relacionan. Por ejemplo, la expansión del Imperio explica por qué el español se habla en América, y la geografía de las costas explica por qué los navegantes pudieron zarpar desde Andalucía. Usa colores, palabras clave y pequeños dibujos. Un buen mapa mental no copia páginas enteras, sino que resume con inteligencia y muestra las relaciones entre las ideas.", "Para escribir tu ensayo, utiliza lo que aprendiste sobre el texto argumentativo. Comienza con una tesis clara, por ejemplo: «Ser español cristiano hoy significa recibir con gratitud una herencia de fe, de cultura y de lengua, y ponerla al servicio de los demás». Después ofrece argumentos apoyados en datos históricos, como la obra de Las Casas, la Biblia traducida al castellano o el legado literario del Siglo de Oro. Usa conectores para enlazar tus ideas y termina con una conclusión que retome la tesis. Recuerda que un ensayo honesto reconoce también las sombras de la historia, porque la verdad no teme a la autocrítica. Revisa la puntuación, la ortografía y la claridad de cada oración antes de entregarlo.", "La presentación oral exige otras destrezas. Ensaya varias veces ante un espejo o ante tu familia, cuida el volumen y la velocidad de tu voz y mira a quienes te escuchan. Organiza tu exposición en introducción, desarrollo y cierre, y respeta el tiempo de seis minutos. Cuando recibas preguntas, escucha con atención, responde con sencillez y admite con humildad lo que no sepas. Hablar en público es una forma de servicio, porque compartes lo que has aprendido para ayudar a otros a comprender. El apóstol Pedro aconseja estar siempre preparados para dar razón de nuestra esperanza, pero con mansedumbre y reverencia, y esa actitud es un modelo excelente para toda argumentación.", "Finalmente, pregúntate qué regalo ha dado Dios a España para bendecir al mundo. Quizás pienses en su lengua compartida por tantos pueblos, en su literatura, en sus santos y misioneros, en su arte, en su hospitalidad o en la herencia de pensadores que defendieron la dignidad humana. Jesús dijo a sus discípulos que son la sal de la tierra y la luz del mundo. La sal da sabor y preserva, y la luz ilumina sin ruido. Ser sal y luz significa vivir con integridad en cualquier lugar donde estemos, ya sea en España o en otro país. Que tu ensayo, tu mapa y tu presentación muestren no solo lo que sabes, sino también quién eres ante Dios y ante los demás."], "glossary": [{"term": "Globalización", "def": "Proceso por el que los países y los pueblos se conectan cada vez más mediante el comercio, las comunicaciones y los viajes."}, {"term": "Identidad", "def": "Conjunto de rasgos, valores e historia que hacen que una persona o un pueblo sea quien es."}, {"term": "Síntesis", "def": "Resumen que reúne de forma ordenada las ideas esenciales de un conjunto de contenidos."}, {"term": "Mapa mental", "def": "Esquema que parte de una idea central y se ramifica en ideas relacionadas."}, {"term": "Ensayo", "def": "Texto en prosa en el que el autor expone y defiende una reflexión personal sobre un tema."}, {"term": "Argumentación oral", "def": "Defensa de una idea mediante razones, expresada en voz alta ante un público."}, {"term": "Herencia cultural", "def": "Conjunto de bienes, costumbres, lengua y creencias que una generación recibe de las anteriores."}], "practice": [{"q": "Explica con tus palabras qué significa que vivimos en un mundo globalizado y menciona una oportunidad y un riesgo.", "feedback": "Significa que los países están muy conectados por el comercio, los viajes y las comunicaciones. Una oportunidad es poder conocer otras culturas y compartir la fe y la lengua con personas de lugares lejanos. Un riesgo es olvidar las propias raíces o pensar que todo es igual. Reconocer ambos aspectos ayuda a vivir con equilibrio."}, {"q": "Elabora una lista de tres ramas para un mapa mental del curso y escribe un dato clave en cada una.", "feedback": "Las tres ramas son Historia, Geografía y Lengua. En Historia, un dato puede ser la labor de Las Casas en defensa de los indígenas; en Geografía, la situación de España en el suroeste de Europa; en Lengua, el español como lengua oficial en cerca de veinte países. Lo importante es elegir datos significativos y conectarlos entre sí."}, {"q": "Redacta una tesis para tu ensayo sobre ser español cristiano en el mundo globalizado.", "feedback": "Una tesis posible es: «Ser español cristiano hoy significa recibir con gratitud una herencia de fe, lengua y cultura, y ponerla al servicio de los demás». Una buena tesis es clara, defendible y se apoya en argumentos que se desarrollan en el texto. Debe evitar frases demasiado vagas o exageradas."}, {"q": "¿Qué significa que somos «sal de la tierra y luz del mundo» y cómo puedes vivirlo en tu vida diaria?", "feedback": "La sal da sabor y preserva, y la luz ilumina; ambas cosas sirven a los demás sin buscar protagonismo. Vivirlo implica actuar con honradez, hablar con verdad, tratar con respeto a quienes piensan distinto y servir a la familia y a la comunidad. Así el testimonio cristiano se hace visible en gestos cotidianos."}], "quiz": [{"q": "¿Qué significa que el mundo está globalizado?", "opts": [{"t": "Que los países están muy conectados por el comercio y las comunicaciones", "ok": true}, {"t": "Que todos los países son iguales", "ok": false}, {"t": "Que ya no existen las fronteras", "ok": false}]}, {"q": "¿Qué es un mapa mental?", "opts": [{"t": "Un esquema que parte de una idea central y se ramifica", "ok": true}, {"t": "Un mapa político de Europa", "ok": false}, {"t": "Una copia completa de un libro", "ok": false}]}, {"q": "¿Con qué debe comenzar un ensayo argumentativo?", "opts": [{"t": "Con una lista de fechas", "ok": false}, {"t": "Con una conclusión sin explicar", "ok": false}, {"t": "Con una tesis clara", "ok": true}]}, {"q": "¿Qué actitud recomienda la lectura al responder preguntas en la presentación oral?", "opts": [{"t": "Escuchar con atención y admitir con humildad lo que no se sabe", "ok": true}, {"t": "Evitar contestar", "ok": false}, {"t": "Insistir en tener siempre la razón", "ok": false}]}, {"q": "¿Qué significan las imágenes de la sal y la luz en Mateo 5?", "opts": [{"t": "Que los cristianos deben aislarse del mundo", "ok": false}, {"t": "Que los cristianos sirven a otros con integridad, dando sabor y claridad", "ok": true}, {"t": "Que los cristianos deben ser famosos", "ok": false}]}], "verify": ["Cita de Mateo 5:13-14 (sal y luz) en la versión empleada por el centro", "Referencia a 1 Pedro 3:15 sobre dar razón de la esperanza con mansedumbre", "Coherencia de los datos de síntesis con lo tratado en las unidades de octubre a junio", "Dato de que el español es lengua oficial en cerca de veinte países (ver unidad de junio)"], "timeline": [{"when": "Paso 1", "what": "Repasa historia, geografía y lengua del curso."}, {"when": "Paso 2", "what": "Haz un mapa mental con «España cristiana en el mundo»."}, {"when": "Paso 3", "what": "Escribe una tesis clara para tu ensayo."}, {"when": "Paso 4", "what": "Añade argumentos con datos históricos y conectores."}, {"when": "Paso 5", "what": "Termina con una conclusión que retome la tesis."}, {"when": "Paso 6", "what": "Revisa puntuación y ortografía; ensaya la presentación."}, {"when": "Paso 7", "what": "Expón en seis minutos y responde a las preguntas."}], "scene": {"icons": ["🧠", "✍️", "🎤"], "palette": "violet"}, "media": [{"title": "Biblia del Oso (1569), portada", "what": "Ejemplo del legado de fe y lengua que puede citarse en el ensayo.", "find": "Biblia del Oso 1569 portada", "note": "Impreso de 1569; dominio público"}, {"title": "Brevísima relación de la destrucción de las Indias (portada)", "what": "Fuente del legado de Las Casas citado en el repaso.", "find": "Brevísima relación de la destrucción de las Indias 1552 portada", "note": "Edición de 1552; dominio público"}, {"title": "Ejemplo de mapa mental", "what": "Modelo visual de cómo ramificar ideas desde una idea central.", "find": "mind map example", "note": "Hay ejemplos libres en Commons; verificar licencia"}]}});
